module pebble_transform (input clk input rst_n input start input [2:0] N input [3:0] K input [7:0] target_circle output reg [7:0] result output reg done); reg [7:0] result_reg; reg [7:0] candidate_cnt; reg [7:0] current_c; reg [2:0] transform_remaining; reg [3:0] N_val; reg [3:0] K_val; reg [2:0] state; reg done_reg; localparam IDLE = 3'd0 LATCH_N_K = 1 INIT_CANDIDATE = 2 APPLY_TRANSFORM =3 CHECK_EQUIVALENCE =4 INCREMENT_RESULT=5 NEXT_CANDIDATE=6 DONE=7; always @(posedge clk) begin if (!rst_n) begin state <= IDLE; result_reg <= 8'd0; candidate_cnt <=8'd0; current_c <=8'd0; transform_remaining <=3'd0; N_val <=4'd0; K_val <=4'd0; done_reg <=1'b0; end else begin case (state) IDLE: begin if (start) state <= LATCH_N_K; else state <= IDLE; end LATCH_N_K: begin N_val <= N; K_val <= K; if (K_val >0) begin transform_remaining <= K_val; state <= INIT_CANDIDATE; end else state <= CHECK_EQUIVALENCE; end INIT_CANDIDATE: begin current_c <= candidate_cnt & ((1 << N_val) -1); if (K_val >0) state <= APPLY_TRANSFORM; else state <= CHECK_EQUIVALENCE; end APPLY_TRANSFORM: begin reg [7:0] next_c; reg [N_val-1:0] c = current_c[N_val-1:0]; for (int i=0; i<N_val; i++) begin int bit_i = c[i]; int next_bit; if (i == N_val-1) next_bit = (bit_i == c[0]) ? 1 :0; else next_bit = (bit_i == c[i+1]) ? 1 :0; next_c[i] = next_bit; end current_c <= { (8 - N_val){1'b0}, next_c }; transform_remaining <= transform_remaining -1; if (transform_remaining >0) state <= APPLY_TRANSFORM; else state <= CHECK_EQUIVALENCE; end CHECK_EQUIVALENCE: begin reg [7:0] target_N = target_circle & ((1 << N_val) -1); reg [N_val-1:0] c = current_c[N_val-1:0]; reg [7:0] match_found = 8'd0; for (int s=0; s<N_val; s++) begin reg [N_val-1:0] rotated_c; for (int i=0; i<N_val; i++) rotated_c[i] = c[(i + s) % N_val]; reg [7:0] rc_val = rotated_c; if (rc_val == target_N) begin match_found = 1; break; end end if (match_found) state <= INCREMENT_RESULT; else state <= NEXT_CANDIDATE; end INCREMENT_RESULT: begin result_reg <= result_reg +1; state <= NEXT_CANDIDATE; end NEXT_CANDIDATE: begin candidate_cnt <= candidate_cnt +1; if (candidate_cnt < (1 << N_val)) state <= INIT_CANDIDATE; else begin state <= DONE; done_reg <=1'b1; end end DONE: state <= DONE; endcase end end assign result = result_reg; assign done = done_reg; endmodule